changeSet.sql:
ALTER TABLE public.gis_road
    ADD COLUMN oneway varchar(4) NOT NULL DEFAULT 'no' CHECK (oneway IN ('no','yes','-1')),
    ADD COLUMN motorcycle_allowed boolean NOT NULL DEFAULT true,
    ADD COLUMN foot_allowed boolean NOT NULL DEFAULT true,
    ADD COLUMN source varchar(20);
CREATE UNIQUE INDEX ux_gis_road_external_id ON public.gis_road (external_id);

DO $$ BEGIN
            IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='police_runtime') THEN
                GRANT SELECT ON public.gis_road TO police_runtime;
            END IF;
        END $$;
